    ["B1", "Pouvez-vous garder mes bagages jusqu'à cet après-midi ?", ["Could you look after my luggage until this afternoon?", "Can you keep my luggage until this afternoon, please?", "Could you store my bags until this afternoon?", "Can I leave my luggage with you until this afternoon?"], [["luggage", "bags", "baggage", "suitcase*"], ["afternoon"], ["keep", "store", "look after", "leave"]], ["Pourriez-vous garder mes valises jusqu'à cet après-midi ?", "Puis-je laisser mes bagages jusqu'à cet après-midi ?"], [["bagages", "valises"], ["apres midi"], ["garder", "laisser"]], "« luggage » est indénombrable : pas de « luggages »."],
    ["B1", "La chambre est bruyante, pourrions-nous en changer ?", ["The room is very noisy. Could we change rooms?", "Our room is too noisy — could we move to another room?", "The room is noisy. Is it possible to change to a quieter one?", "It's very noisy in our room. Could we have a different room?"], [["noisy", "noise"], ["room"], ["change", "move", "different", "another", "quieter"]], ["La chambre est très bruyante, pouvons-nous en avoir une autre ?", "Notre chambre est bruyante, peut-on la changer ?"], [["bruyant*", "bruit"], ["chambre"], ["changer", "autre", "calme"]], "« Is it possible to… ? » est très poli."],
    ["B1", "Pouvez-vous nous appeler un taxi pour demain matin à sept heures ?", ["Could you book us a taxi for seven tomorrow morning?", "Could you order a taxi for tomorrow morning at seven o'clock?", "Could you call us a taxi for seven a.m. tomorrow?", "Would you mind ordering a taxi for tomorrow at 7 a.m.?"], [["taxi"], ["seven", "7"], ["tomorrow"]], ["Pourriez-vous réserver un taxi pour demain à sept heures ?", "Pouvez-vous commander un taxi pour 7 h demain matin ?"], [["taxi"], ["sept", "7"], ["demain"]], "« 7 a.m. » ou « seven in the morning »."],
    ["A2", "Je voudrais prolonger mon séjour d'une nuit.", ["I'd like to extend my stay by one night.","Could I stay one more night?","I'd like to stay an extra night.","Can I extend my stay for another night?"], [["extend*","extra","another","more","longer"],["night"]], ["Puis-je rester une nuit de plus ?","Je voudrais rester une nuit supplémentaire."], [["prolong*","rester","de plus","encore","supplementaire"],["nuit"]], "« extend » = prolonger ; « an extra night » = une nuit de plus."],
    ["B1", "Il n'y a pas d'eau chaude dans la salle de bain depuis ce matin.", ["There's been no hot water in the bathroom since this morning.", "We haven't had any hot water in the bathroom since this morning.", "There's no hot water in my bathroom, and there hasn't been since this morning.", "The bathroom has had no hot water since this morning."], [["no", "haven't", "hasn't", "not", "without"], ["hot", "warm"], ["water"], ["bathroom", "shower", "bath"]], ["Nous n'avons pas d'eau chaude dans la salle de bain depuis ce matin.", "Depuis ce matin, il n'y a plus d'eau chaude dans la salle de bain."], [["pas", "plus", "sans"], ["eau"], ["chaude", "chaud"], ["bain", "douche"], ["matin"]], "« since this morning » : point de départ = « since » ; durée = « for »."]
